INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64310316', 64310316, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Tenaga Alih Daya Tenaga  Tenaga Pendukung Kesekretariatan Pelaksanaan P3TB', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 179454230, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Melaksanakan tugas-tugas pengolahan data ekonomi dan data lain di lingkup ekonomi kreatif, termasuk pengumpulan data, analisis data, penyusunan proyeksi data, koordinasi data dengan mitra terkait, penyajian data, dan pengarsipan data. 2. Terlibat dalam pengolahan data pembangunan ekonomi kreatif, penulisan laporan triwulanan bidang ekonomi kreatif, analisis proyeksi indikator pembangunan ekonomi kreatif, penyusunan kajian subsektoral ekonomi kreatif, dan pengolahan data lain di lingkup ekonomi kreatif. 3. Menyiapkan bahan rapat, notulensi, dan dokumentasi kegiatan (baik internal maupun eksternal) serta memastikan kelengkapan administrasi pendukungnya. 4. Melaksanakan entri data dan pengelolaan sistem informasi administrasi Direktorat dan mitra pembangunan terkait, termasuk pembantuan pemrosesan data di platform digital sesuai instruksi atasan. 5. Membantu proses pengolahan data dan penyusunan arsip digital untuk mendukung', '1. Laporan pelaksanaan pengolahan data secara berkala, yang memuat informasi pengumpulan data, analisis data, penyusunan proyeksi data, penyajian data, pengarsipan data, dan koordinasi data dengan mitra terkait. 2. Tersedianya pemutakhiran data dalam database pembangunan yang terstruktur. 3. Tersediaya database terstruktur dan dokumen metadata 4. Terlaksananya kegiatan administrasi pendukung secara tepat waktu dan sesuai prosedur, termasuk penyusunan bahan rapat, notulensi, serta dukungan administrasi rapat dan perjalanan dinas. 5. Tersusunya laporan perkembangan pembangunan dalam periode triwulanan. 6. Dokumentasi hasil kerja pengolahan data maupun administrasi yang terarsip dengan baik sebagai bahan audit internal maupun eksternal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1434782);
