INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64311350', 64311350, 'analyze_legacy', 'Komisi Pemilihan Umum', 'central', 'KPU  KOTA PADANG PANJANG', 'Belanja Honor Operasional Satuan Kerja Layanan Perkantoran', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sumatera Barat, Padang Panjang (Kota)', 64812000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PKT', 'Akun 521115 (Belanja Honor Operasional Satuan Kerja) dalam bagan akun standar (BAS) digunakan untuk menampung pembayaran honorarium tidak tetap yang terkait dengan kegiatan operasional rutin satuan kerja (satker). Ini mencakup honor pengelola keuangan (PPK, PPSPM, Bendahara), pengelola PNBP, dan tim SAI, yang dibayarkan terus-menerus.', 'Detail Penggunaan Akun 521115: Jenis Belanja: Belanja Barang. Fungsi: Honorarium menunjang kegiatan operasional satker (bukan output kegiatan spesifik). Contoh: Honor pejabat kuasa pengguna anggaran (KPA), Pejabat Pembuat Komitmen (PPK), Penguji SPP, Penanda tangan SPM, Bendahara Pengeluaran, Staf Pengelola Keuangan, dan Pengelola SAK/SIMAK-BMN. Karakteristik: Dibayarkan secara terus-menerus dari awal hingga akhir tahun anggaran. Akun ini berbeda dengan 521213 (Belanja Honor Output Kegiatan) yang dikaitkan dengan output kegiatan tertentu, bukan operasional rutin.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1437113);
