INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64311466', 64311466, 'analyze_legacy', 'Komisi Pemilihan Umum', 'central', 'KPU  KOTA PADANG PANJANG', 'Belanja Barang Operasional Lainnya Pakaian Dinas Layanan Perkantoran', 'Barang', 'Pengadaan Langsung', 'Sumatera Barat, Padang Panjang (Kota)', 25850000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PKT', 'Akun 521119 (Belanja Barang Operasional Lainnya) dalam Bagan Akun Standar (BAS) pemerintah Indonesia adalah mata anggaran yang digunakan untuk menampung pengeluaran pengadaan barang operasional sehari-hari yang tidak dapat ditampung dalam akun belanja operasional lainnya (seperti belanja keperluan perkantoran, daya/jasa, atau pemeliharaan).', 'Berikut rinciannya: Fungsi: Menampung pengeluaran operasional rutin, contohnya pemeriksaan kesehatan pegawai (medical check-up). Kategori: Termasuk dalam kelompok Belanja Barang (52), sub-kelompok Belanja Barang Operasional (5211). Karakteristik: Digunakan untuk operasional non-BLU (Badan Layanan Umum). Pencatatan: Biasanya digunakan untuk membiayai kegiatan yang mendukung operasional sehari-hari satuan kerja (satker). Akun ini merupakan bagian dari akun belanja barang operasional yang umum digunakan dalam DIPA (Daftar Isian Pelaksanaan Anggaran) kementerian/lembaga.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1439605);
